package app

import app.repositories.MemoryPatientRepository
import app.repositories.MemoryRoomRepository
import app.repositories.PatientRepository
import app.repositories.RoomRepository

/** The in-memory repositories, for tests and for trying the services without a database. */
class MemoryUnitOfWork : UnitOfWork {
    override val patients: PatientRepository = MemoryPatientRepository()
    override val rooms: RoomRepository = MemoryRoomRepository()

    /** Memory has no transactions: changes are kept as they are made. */
    override fun <T> transaction(work: (UnitOfWork) -> T): T = work(this)
}

