package app

import app.repositories.PatientRepository
import app.repositories.RoomRepository
import app.repositories.MongoPatientRepository
import app.repositories.MongoRoomRepository

/** The repositories over one Db, and its transaction. */
class MongoUnitOfWork(val db: Db) : UnitOfWork {
    override val patients: PatientRepository = MongoPatientRepository(db)
    override val rooms: RoomRepository = MongoRoomRepository(db)

    /** Joins the transaction already open, or opens one. */
    override fun <T> transaction(work: (UnitOfWork) -> T): T {
        // Joins the transaction already open
        if (db.inTransaction) return work(this)
        db.begin()
        try {
            val result = work(this)
            db.commit()
            return result
        } catch (error: Throwable) {
            db.rollback()
            throw error
        }
    }
}

