package app.repositories

import app.common.CursorPage
import app.entities.Patient
import java.time.Instant
import org.bson.types.ObjectId

/** Keeps patients rows in memory, for tests and for trying the services without a database. */
class MemoryPatientRepository : PatientRepository {
    private val rows = linkedMapOf<List<Any?>, Patient>()

    /** The key of a row, as a list of its key values. */
    private fun keyOf(row: Patient): List<Any?> = listOf(row.id)

    /** Orders two keys value by value. */
    @Suppress("UNCHECKED_CAST")
    private fun compareKeys(a: List<Any?>, b: List<Any?>): Int {
        for (index in a.indices) {
            val order = compareValues(a[index] as Comparable<Any>?, b[index] as Comparable<Any>?)
            if (order != 0) return order
        }
        return 0
    }

    private fun visible(): List<Patient> =
        rows.values.filter { true }.sortedWith { a, b -> compareKeys(keyOf(a), keyOf(b)) }

    override fun findById(id: String): Patient? {
        return visible().firstOrNull { it.id == id }
    }

    override fun list(after: List<Any>?, limit: Int): CursorPage<Patient> {
        val rows = visible().filter { after == null || compareKeys(keyOf(it), after) > 0 }
        val items = rows.take(limit)
        return CursorPage(items, if (rows.size > limit) keyOf(items.last()).map { it!! } else null)
    }

    override fun findByDocument(document: String): Patient? {
        return visible().firstOrNull { it.document == document }
    }

    override fun findAllByBirth(birth: Instant): List<Patient> {
        return visible().filter { it.birth == birth }
    }

    override fun insert(entity: Patient): Patient {
        entity.id = entity.id ?: ObjectId().toHexString()
        rows[keyOf(entity)] = entity
        return entity
    }

    override fun update(entity: Patient): Patient {
        rows[keyOf(entity)] = entity
        return entity
    }

    override fun delete(entity: Patient): Unit {
        rows.remove(keyOf(entity))
    }

    override fun addContact(id: String, contact: Patient.Contact): Patient? {
        val found = visible().firstOrNull { it.id == id } ?: return null
        found.contacts = found.contacts.orEmpty() + listOf(contact)
        found.version = (found.version ?: 0) + 1
        return found
    }

    override fun removeContact(id: String, position: Int, size: Int): Patient? {
        val found = visible().firstOrNull { it.id == id } ?: return null
        if (found.contacts.orEmpty().size != size) return null
        found.contacts = found.contacts.orEmpty().filterIndexed { index, _ -> index != position }
        found.version = (found.version ?: 0) + 1
        return found
    }
}

