package app.repositories

import app.Db
import app.Documents
import app.common.CursorPage
import app.entities.Patient
import java.time.Instant
import java.util.Collections
import java.util.Date
import java.util.WeakHashMap
import org.bson.Document
import org.bson.types.Binary
import org.bson.types.Decimal128
import org.bson.types.ObjectId

/** Keeps patients rows in the database, through the MongoDB driver. It runs in the transaction already open, when there is one. */
class MongoPatientRepository(private val db: Db) : PatientRepository {
    private val collection = "patients"

    /** The fields a change may write */
    private val fields = listOf("name", "birth", "weight", "balance", "document", "photo", "visits", "blood", "contacts", "insurance", "version")

    override fun findById(id: String): Patient? {
        if (!ObjectId.isValid(id)) return null
        return db.find(collection, Document("_id", ObjectId(id)), limit = 1).firstOrNull()?.let { loaded(it) }
    }

    override fun list(after: List<Any>?, limit: Int): CursorPage<Patient> {
        val filter = Document()
        if (after != null) filter["_id"] = Document("\$gt", ObjectId(after[0] as String))
        val rows = db.find(collection, filter, sort = Document("_id", 1), limit = limit + 1).map { loaded(it) }
        val items = rows.take(limit)
        return CursorPage(items, if (rows.size > limit) listOf(items.last().id!!) else null)
    }

    override fun findByDocument(document: String): Patient? {
        return db.find(collection, Document("document", document), limit = 1).firstOrNull()?.let { loaded(it) }
    }

    override fun findAllByBirth(birth: Instant): List<Patient> {
        return db.find(collection, Document("birth", Date.from(birth)), sort = Document("_id", 1)).map { loaded(it) }
    }

    override fun insert(entity: Patient): Patient {
        entity.id = entity.id ?: ObjectId().toHexString()
        db.insert("Patient", collection, toDocument(entity))
        READ[entity] = Documents.copy(toDocument(entity)) as Document
        return entity
    }

    override fun update(entity: Patient): Patient {
        val now = toDocument(entity)
        val changes = Documents.changes(READ[entity], now, fields)
        if (changes.isNotEmpty()) {
            db.update("Patient", collection, Document("_id", now["_id"]), changes)
        }
        READ[entity] = Documents.copy(now) as Document
        return entity
    }

    override fun delete(entity: Patient): Unit {
        db.delete("Patient", collection, Document("_id", ObjectId(entity.id!!)))
    }

    override fun addContact(id: String, contact: Patient.Contact): Patient? {
        if (!ObjectId.isValid(id)) return null
        val change = Document("\$push", Document("contacts", contactToDocument(contact))).append("\$inc", Document("version", 1))
        return db.change("Patient", collection, Document("_id", ObjectId(id)), change)?.let { loaded(it) }
    }

    override fun removeContact(id: String, position: Int, size: Int): Patient? {
        if (!ObjectId.isValid(id)) return null
        val head = Document("\$slice", listOf("\$contacts", position))
        val tail = Document("\$slice", listOf("\$contacts", position + 1, maxOf(size, 1)))
        val change = listOf(Document("\$set", Document("contacts", Document("\$concatArrays", listOf(head, tail))).append("version", Document("\$add", listOf("\$version", 1)))))
        return db.rewrite("Patient", collection, Document("_id", ObjectId(id)).append("contacts", Document("\$size", size)), change)?.let { loaded(it) }
    }

    /** The entity of a document, with the document kept to tell its changes. */
    private fun loaded(document: Document): Patient {
        val entity = fromDocument(document)
        READ[entity] = Documents.copy(toDocument(entity)) as Document
        return entity
    }

    /** The document of a Patient: what is null is left out. */
    private fun toDocument(value: Patient): Document {
        val document = Document()
        value.id?.let { document["_id"] = ObjectId(it) }
        value.name?.let { document["name"] = it }
        value.birth?.let { document["birth"] = Date.from(it) }
        value.weight?.let { document["weight"] = it }
        value.balance?.let { document["balance"] = Decimal128(it) }
        value.document?.let { document["document"] = it }
        value.photo?.let { document["photo"] = Binary(it) }
        value.visits?.let { document["visits"] = it }
        value.blood?.let { document["blood"] = it }
        value.contacts?.let { held -> document["contacts"] = held.map { contactToDocument(it) } }
        value.insurance?.let { document["insurance"] = insuranceToDocument(it) }
        value.version?.let { document["version"] = it }
        return document
    }

    private fun fromDocument(document: Document): Patient =
        Patient(
            id = document["_id"]?.toString(),
            name = document["name"] as String?,
            birth = (document["birth"] as Date?)?.toInstant(),
            weight = (document["weight"] as Number?)?.toDouble(),
            balance = Documents.decimal(document["balance"]),
            document = document["document"] as String?,
            photo = (document["photo"] as Binary?)?.data,
            visits = (document["visits"] as Number?)?.toInt(),
            blood = document["blood"] as String?,
            contacts = (document["contacts"] as List<*>?)?.mapNotNull { (it as Document?)?.let { contactFromDocument(it) } },
            insurance = (document["insurance"] as Document?)?.let { insuranceFromDocument(it) },
            version = (document["version"] as Number?)?.toInt(),
        )

    /** The document of a Patient.Contact: what is null is left out. */
    private fun contactToDocument(value: Patient.Contact): Document {
        val document = Document()
        value.kind?.let { document["kind"] = it }
        value.value?.let { document["value"] = it }
        return document
    }

    private fun contactFromDocument(document: Document): Patient.Contact =
        Patient.Contact(
            kind = document["kind"] as String?,
            value = document["value"] as String?,
        )

    /** The document of a Patient.Insurance: what is null is left out. */
    private fun insuranceToDocument(value: Patient.Insurance): Document {
        val document = Document()
        value.company?.let { document["company"] = it }
        value.since?.let { document["since"] = Date.from(it) }
        return document
    }

    private fun insuranceFromDocument(document: Document): Patient.Insurance =
        Patient.Insurance(
            company = document["company"] as String?,
            since = (document["since"] as Date?)?.toInstant(),
        )

    private companion object {
        /** The document each entity was read from: a change writes only the fields that differ */
        val READ: MutableMap<Patient, Document> = Collections.synchronizedMap(WeakHashMap())
    }
}

