package app.services

import app.UnitOfWork
import app.common.CursorPage
import app.dtos.PatientCreate
import app.dtos.PatientRead
import app.dtos.PatientUpdate
import app.entities.Patient
import app.errors.ConflictException
import app.errors.FieldError
import app.errors.NotFoundException
import app.errors.ValidationFailedException
import java.math.BigDecimal
import java.time.Instant

/** Operations on patients. Each write runs in its own transaction. */
@Suppress("UNCHECKED_CAST")
class PatientService(private val unitOfWork: UnitOfWork) {
    /** Stores a new Patient after checking it. */
    fun createPatient(data: PatientCreate): PatientRead {
        val values = mapOf(
            "name" to data.name,
            "birth" to data.birth,
            "weight" to data.weight,
            "balance" to data.balance,
            "document" to data.document,
            "photo" to data.photo,
            "visits" to data.visits,
            "blood" to data.blood,
            "contacts" to data.contacts,
            "insurance" to data.insurance,
            "version" to data.version,
        ).filterValues { it != null }
        return unitOfWork.transaction { uow ->
            checkValues(uow, values, null)
            val entity = Patient()
            applyValues(entity, values)
            read(uow.patients.insert(entity))
        }
    }

    /** The Patient with this key; NotFoundException when there is none. */
    fun getPatient(id: String): PatientRead = read(find(unitOfWork, id))

    /** A page of patients after the key after (null for the first page), by primary key. */
    fun listPatients(after: List<Any>?, limit: Int): CursorPage<PatientRead> = unitOfWork.patients.list(after, limit).map { read(it) }

    /** Changes the given values of a Patient, read at version. */
    fun updatePatient(id: String, changes: PatientUpdate, version: Int): PatientRead {
        val values = given(changes)
        return unitOfWork.transaction { uow ->
            val current = find(uow, id)
            if (current.version != version)
                throw ConflictException("Patient", "was changed by someone else since it was read", listOf("version"))
            checkValues(uow, values, current)
            applyValues(current, values)
            current.version = version + 1
            read(uow.patients.update(current))
        }
    }

    /** Deletes a Patient. */
    fun deletePatient(id: String, version: Int) {
        unitOfWork.transaction { uow ->
            val current = find(uow, id)
            if (current.version != version)
                throw ConflictException("Patient", "was changed by someone else since it was read", listOf("version"))
            uow.patients.delete(current)
        }
    }

    /** The Patient with this document, or null. */
    fun findPatientByDocument(document: String): PatientRead? = unitOfWork.patients.findByDocument(document)?.let { read(it) }

    /** Adds an item to contacts, read at version. */
    fun addContact(id: String, contact: Patient.Contact, version: Int): PatientRead {
        val errors = mutableListOf<FieldError>()
        checkContact(contact, "contacts", errors)
        if (errors.isNotEmpty()) throw ValidationFailedException("Patient", errors)
        return unitOfWork.transaction { uow ->
            val current = find(uow, id)
            if (current.version != version)
                throw ConflictException("Patient", "was changed by someone else since it was read", listOf("version"))
            read(uow.patients.addContact(id, contact) ?: throw NotFoundException("Patient", id))
        }
    }

    /** Removes an item from contacts, by its position, read at version. */
    fun removeContact(id: String, position: Int, version: Int): PatientRead {
        return unitOfWork.transaction { uow ->
            val current = find(uow, id)
            if (current.version != version)
                throw ConflictException("Patient", "was changed by someone else since it was read", listOf("version"))
            if (position !in current.contacts.orEmpty().indices) throw NotFoundException("Contact", position)
            read(uow.patients.removeContact(id, position, current.contacts.orEmpty().size) ?: throw ConflictException("Patient", "was changed by someone else since it was read", listOf("contacts")))
        }
    }

    /** Checks the values against the rules of the "patients" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private fun validate(uow: UnitOfWork, values: Map<String, Any?>, current: Patient?) {
        val creating = current == null
        val errors = mutableListOf<FieldError>()
        run {
            val value = values["name"]
            if (value == null) {
                if (creating || "name" in values) errors += FieldError("name", "is required")
            } else {
                if (value is String && value.length > 80) errors += FieldError("name", "is longer than 80 characters")
                if (!(value.toString().length >= 2)) errors += FieldError("name", "must have >= 2 characters")
            }
        }
        run {
            val value = values["birth"]
            if (value == null) {
                if (creating || "birth" in values) errors += FieldError("birth", "is required")
            }
        }
        run {
            val value = values["visits"]
            if (value == null) {
                if (creating || "visits" in values) errors += FieldError("visits", "is required")
            } else {
                if (!((value as Number).toDouble() >= 0.0)) errors += FieldError("visits", "must be >= 0")
            }
        }
        run {
            val value = values["blood"]
            if (value != null) {
                if (value.toString() !in listOf("A", "B", "O")) errors += FieldError("blood", "must be one of: A, B, O")
            }
        }
        run {
            val value = values["contacts"]
            if (value == null) {
                if (creating || "contacts" in values) errors += FieldError("contacts", "is required")
            } else {
                val document = value as List<Patient.Contact>
                document.forEachIndexed { i0, item0 ->
                    checkContact(item0, "contacts" + "." + i0, errors)
                }
            }
        }
        run {
            val value = values["insurance"]
            if (value != null) {
                val document = value as Patient.Insurance
                checkInsurance(document, "insurance", errors)
            }
        }
        if (errors.isNotEmpty()) throw ValidationFailedException("Patient", errors)
    }

    /** Values that must be unique are not taken by another row. */
    private fun checkUnique(uow: UnitOfWork, values: Map<String, Any?>, current: Patient?) {
        run {
            val document = if ("document" in values) values["document"] as String? else current?.document
            if (document != null) {
                val other = uow.patients.findByDocument(document)
                if (other != null && (current == null || other.id != current.id))
                    throw ConflictException("Patient", "document is already taken", listOf("document"))
            }
        }
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private fun checkValues(uow: UnitOfWork, values: Map<String, Any?>, current: Patient?) {
        validate(uow, values, current)
        checkUnique(uow, values, current)
    }

    /** Sets the given values on the entity. */
    private fun applyValues(entity: Patient, values: Map<String, Any?>) {
        if ("name" in values) entity.name = values["name"] as String?
        if ("birth" in values) entity.birth = values["birth"] as Instant?
        if ("weight" in values) entity.weight = values["weight"] as Double?
        if ("balance" in values) entity.balance = values["balance"] as BigDecimal?
        if ("document" in values) entity.document = values["document"] as String?
        if ("photo" in values) entity.photo = values["photo"] as ByteArray?
        if ("visits" in values) entity.visits = values["visits"] as Int?
        if ("blood" in values) entity.blood = values["blood"] as String?
        if ("contacts" in values) entity.contacts = values["contacts"] as List<Patient.Contact>?
        if ("insurance" in values) entity.insurance = values["insurance"] as Patient.Insurance?
        if ("version" in values) entity.version = values["version"] as Int?
    }

    /** The Patient with this key; NotFoundException when there is none. */
    private fun find(uow: UnitOfWork, id: String): Patient =
        uow.patients.findById(id) ?: throw NotFoundException("Patient", id)

    /** The Patient as services return it. */
    private fun read(entity: Patient): PatientRead =
        PatientRead(
            id = entity.id!!,
            name = entity.name!!,
            birth = entity.birth!!,
            weight = entity.weight,
            balance = entity.balance,
            document = entity.document,
            photo = entity.photo,
            visits = entity.visits!!,
            blood = entity.blood,
            contacts = entity.contacts!!,
            insurance = entity.insurance,
            version = entity.version,
        )

    /** The values an update gives, by field. */
    private fun given(changes: PatientUpdate): Map<String, Any?> {
        val values = mutableMapOf<String, Any?>()
        values["name"] = changes.name
        values["birth"] = changes.birth
        values["weight"] = changes.weight
        values["balance"] = changes.balance
        values["document"] = changes.document
        values["photo"] = changes.photo
        values["visits"] = changes.visits
        values["blood"] = changes.blood
        values["contacts"] = changes.contacts
        values["insurance"] = changes.insurance
        values["version"] = changes.version
        return values
    }

    /** What a Patient.Contact does not follow of its rules, each with the path of its field. */
    private fun checkContact(value: Patient.Contact, path: String, errors: MutableList<FieldError>) {
        value.kind.let { held ->
            if (held == null) errors += FieldError(path + ".kind", "is required")
            else {
                if (held !in listOf("phone", "email")) errors += FieldError(path + ".kind", "must be one of: phone, email")
            }
        }
        if (value.value == null) errors += FieldError(path + ".value", "is required")
    }

    /** What a Patient.Insurance does not follow of its rules, each with the path of its field. */
    @Suppress("UNUSED_PARAMETER")
    private fun checkInsurance(value: Patient.Insurance, path: String, errors: MutableList<FieldError>) {
