package app.services

import app.UnitOfWork
import app.common.CursorPage
import app.dtos.RoomCreate
import app.dtos.RoomRead
import app.dtos.RoomUpdate
import app.entities.Room
import app.errors.FieldError
import app.errors.NotFoundException
import app.errors.ValidationFailedException

/** Operations on rooms. Each write runs in its own transaction. */
class RoomService(private val unitOfWork: UnitOfWork) {
    /** Stores a new Room after checking it. */
    fun createRoom(data: RoomCreate): RoomRead {
        val values = mapOf(
            "code" to data.code,
            "beds" to data.beds,
        ).filterValues { it != null }
        return unitOfWork.transaction { uow ->
            checkValues(uow, values, null)
            val entity = Room()
            applyValues(entity, values)
            read(uow.rooms.insert(entity))
        }
    }

    /** The Room with this key; NotFoundException when there is none. */
    fun getRoom(id: String): RoomRead = read(find(unitOfWork, id))

    /** A page of rooms after the key after (null for the first page), by primary key. */
    fun listRooms(after: List<Any>?, limit: Int): CursorPage<RoomRead> = unitOfWork.rooms.list(after, limit).map { read(it) }

    /** Changes the given values of a Room. */
    fun updateRoom(id: String, changes: RoomUpdate): RoomRead {
        val values = given(changes)
        return unitOfWork.transaction { uow ->
            val current = find(uow, id)
            checkValues(uow, values, current)
            applyValues(current, values)
            read(uow.rooms.update(current))
        }
    }

    /** Deletes a Room. */
    fun deleteRoom(id: String) {
        unitOfWork.transaction { uow ->
            val current = find(uow, id)
            uow.rooms.delete(current)
        }
    }

    /** Checks the values against the rules of the "rooms" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private fun validate(uow: UnitOfWork, values: Map<String, Any?>, current: Room?) {
        val creating = current == null
        val errors = mutableListOf<FieldError>()
        run {
            val value = values["code"]
            if (value == null) {
                if (creating || "code" in values) errors += FieldError("code", "is required")
            }
        }
        if (errors.isNotEmpty()) throw ValidationFailedException("Room", errors)
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private fun checkValues(uow: UnitOfWork, values: Map<String, Any?>, current: Room?) {
        validate(uow, values, current)
    }

    /** Sets the given values on the entity. */
    private fun applyValues(entity: Room, values: Map<String, Any?>) {
        if ("code" in values) entity.code = values["code"] as String?
        if ("beds" in values) entity.beds = values["beds"] as Long?
    }

    /** The Room with this key; NotFoundException when there is none. */
    private fun find(uow: UnitOfWork, id: String): Room =
        uow.rooms.findById(id) ?: throw NotFoundException("Room", id)

    /** The Room as services return it. */
    private fun read(entity: Room): RoomRead =
        RoomRead(
            id = entity.id!!,
            code = entity.code!!,
            beds = entity.beds,
        )

    /** The values an update gives, by field. */
    private fun given(changes: RoomUpdate): Map<String, Any?> {
        val values = mutableMapOf<String, Any?>()
        values["code"] = changes.code
        values["beds"] = changes.beds
        return values
    }
}

