import java.math.BigDecimal
import java.time.Instant
import java.time.LocalDateTime
import java.time.ZoneOffset

/** Rows for the tests: valid values for every column, and the rows they point to. */
object Factories {
    /** A valid Patient that is not stored yet; n makes its unique values differ. */
    fun newPatient(n: Int): Patient =
        Patient(
            name = "name-$n",
            birth = LocalDateTime.of(2026, 1, n % 28 + 1, 12, 0).toInstant(ZoneOffset.UTC),
            weight = n + 0.5,
            balance = BigDecimal("${n % 10000}.50"),
            document = "document-$n",
            photo = byteArrayOf(n.toByte()),
            visits = n,
            blood = "A",
            contacts = listOf(newPatientContact(n)),
            insurance = newPatientInsurance(n),
            version = n,
        )

    /** A stored Patient. */
    fun addPatient(uow: UnitOfWork, n: Int): Patient {
        val entity = newPatient(n)
        return uow.patients.insert(entity)
    }

    /** A valid Patient.Contact; n makes its values differ. */
    fun newPatientContact(n: Int): Patient.Contact =
        Patient.Contact(
            kind = "phone",
            value = "value-$n",
        )

    /** A valid Patient.Insurance; n makes its values differ. */
    fun newPatientInsurance(n: Int): Patient.Insurance =
        Patient.Insurance(
            company = "company-$n",
            since = LocalDateTime.of(2026, 1, n % 28 + 1, 12, 0).toInstant(ZoneOffset.UTC),
        )

    /** A valid Room that is not stored yet; n makes its unique values differ. */
    fun newRoom(n: Int): Room =
        Room(
            code = "code-$n",
            beds = n.toLong(),
        )

    /** A stored Room. */
    fun addRoom(uow: UnitOfWork, n: Int): Room {
        val entity = newRoom(n)
        return uow.rooms.insert(entity)
    }
}

