import kotlin.test.assertTrue

/** The service of the "patients" table, on the in-memory repositories. */
class PatientServiceTest {
    private lateinit var uow: MemoryUnitOfWork

    @BeforeTest
    fun open() {
        uow = MemoryUnitOfWork()
    }

    @Test
    fun createsAValidRow() {
        val service = PatientService(uow)
        val row = Factories.newPatient(1)
        val created = service.createPatient(createOf(row))
        val found = service.getPatient(created.id)
        assertEquals(created.id, found.id)
    }

    @Test
    fun refusesAMissingValue() {
        val service = PatientService(uow)
        val row = Factories.newPatient(1)
        row.name = null
        val error = assertFailsWith<ValidationFailedException> { service.createPatient(createOf(row)) }
        assertEquals(listOf("name"), error.errors.map { it.field })
    }

    @Test
    fun refusesARepeatedUniqueValue() {
        val service = PatientService(uow)
        val row = Factories.newPatient(1)
        val first = service.createPatient(createOf(row))
        val again = Factories.newPatient(2)
        again.document = first.document
        assertFailsWith<ConflictException> { service.createPatient(createOf(again)) }
    }

    @Test
    fun keepsItsOwnUniqueValue() {
        val service = PatientService(uow)
        val row = Factories.newPatient(1)
        val created = service.createPatient(createOf(row))
        val updated = service.updatePatient(created.id, PatientUpdate(name = row.name!!, birth = row.birth!!, weight = row.weight, balance = row.balance, document = created.document, photo = row.photo, visits = row.visits!!, blood = row.blood, contacts = row.contacts!!, insurance = row.insurance, version = row.version), created.version!!)
        assertEquals(created.document, updated.document)
    }

    @Test
    fun saysWhenARowIsMissing() {
        val service = PatientService(uow)
        assertFailsWith<NotFoundException> { service.getPatient("ffffffffffffffffffffffff") }
    }

    @Test
    fun deletesARow() {
        val service = PatientService(uow)
        val row = Factories.newPatient(1)
        val created = service.createPatient(createOf(row))
        service.deletePatient(created.id, created.version!!)
        assertFailsWith<NotFoundException> { service.getPatient(created.id) }
    }

    @Test
    fun addsAndRemovesOneItemOfContacts() {
        val n = 7
        val service = PatientService(uow)
        val row = Factories.newPatient(1)
        val created = service.createPatient(createOf(row))
        val before = created.contacts.size
        val item: Patient.Contact = Factories.newPatientContact(n)
        val added = service.addContact(created.id, item, created.version!!)
        assertEquals(before + 1, added.contacts.size)
        val removed = service.removeContact(created.id, before, added.version!!)
        assertEquals(before, removed.contacts.size)
        assertFailsWith<NotFoundException> { service.removeContact(created.id, 99, removed.version!!) }
    }

    /** The create DTO of a row the factories made. */
    private fun createOf(row: Patient) = PatientCreate(
        name = row.name,
        birth = row.birth,
        weight = row.weight,
        balance = row.balance,
        document = row.document,
        photo = row.photo,
        visits = row.visits,
        blood = row.blood,
        contacts = row.contacts,
        insurance = row.insurance,
        version = row.version,
    )
}

